import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # ---- Build initial state dict from target_state ----
    state = {}
    for row in target_state.itertuples(index=False):
        order_id = row.order_id
        state[order_id] = {
            "status": row.status,
            "amount": row.amount,
            "last_seq": row.last_seq,
        }

    # Remember original last_seq per order (for the replay guard) --
    # this must reflect the state BEFORE any event in this batch is applied.
    initial_last_seq = {oid: v["last_seq"] for oid, v in state.items()}

    # ---- Deduplicate events: same seq delivered more than once -> apply once ----
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # ---- Apply replay guard ----
    def passes_guard(row):
        oid = row.order_id
        if oid in initial_last_seq:
            return row.seq > initial_last_seq[oid]
        return True

    if len(cdc_events) > 0:
        mask = cdc_events.apply(passes_guard, axis=1)
        remaining = cdc_events[mask].copy()
    else:
        remaining = cdc_events.copy()

    # ---- Sort remaining events by seq ascending (the only trusted order) ----
    remaining = remaining.sort_values(by="seq", kind="mergesort")

    last_op_applied = {}
    last_applied_seq = {}

    for row in remaining.itertuples(index=False):
        seq = row.seq
        order_id = row.order_id
        op = row.op
        status = row.status
        amount = row.amount

        if op in ("I", "U"):
            if order_id in state:
                existing = state[order_id]
                if op == "U" and pd.isna(amount):
                    new_amount = existing["amount"]
                else:
                    new_amount = amount
                state[order_id] = {
                    "status": status,
                    "amount": new_amount,
                    "last_seq": seq,
                }
            else:
                state[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq,
                }
            last_op_applied[order_id] = op
            last_applied_seq[order_id] = seq

        elif op == "D":
            if order_id in state:
                del state[order_id]
                last_op_applied[order_id] = "D"
                last_applied_seq[order_id] = seq
            # 'D' for a missing order does nothing at all (no record is kept)

    # ---- Build new_state output ----
    new_state_cols = ["order_id", "status", "amount", "last_seq"]
    if state:
        new_state_rows = [
            {
                "order_id": oid,
                "status": v["status"],
                "amount": v["amount"],
                "last_seq": v["last_seq"],
            }
            for oid, v in state.items()
        ]
        new_state = pd.DataFrame(new_state_rows, columns=new_state_cols)
    else:
        new_state = pd.DataFrame(columns=new_state_cols)

    # Coerce dtypes to match expectations
    if len(new_state) > 0:
        new_state["order_id"] = new_state["order_id"].astype(
            target_state["order_id"].dtype if len(target_state) > 0 else "int64"
        )
        new_state["last_seq"] = new_state["last_seq"].astype(
            target_state["last_seq"].dtype if len(target_state) > 0 else "int64"
        )
    else:
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")

    # ---- Build tombstones output ----
    tomb_cols = ["order_id", "deleted_seq"]
    tomb_rows = []
    for oid, op in last_op_applied.items():
        if op == "D":
            tomb_rows.append(
                {"order_id": oid, "deleted_seq": last_applied_seq[oid]}
            )

    if tomb_rows:
        tombstones = pd.DataFrame(tomb_rows, columns=tomb_cols)
        tombstones["order_id"] = tombstones["order_id"].astype(
            target_state["order_id"].dtype if len(target_state) > 0 else "int64"
        )
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype(
            cdc_events["seq"].dtype if len(cdc_events) > 0 else "int64"
        )
    else:
        tombstones = pd.DataFrame(columns=tomb_cols)
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")

    return {"new_state": new_state, "tombstones": tombstones}
